const r = $input.first().json;
const status = Number(r.statusCode ?? r.status ?? 0);
const h = r.headers ?? {};
const raw = r.body ?? r.data ?? '';
let body = raw;
if (typeof raw === 'string') { try { body = JSON.parse(raw); } catch {} }
let msg = '';
if (status >= 400 && body && typeof body === 'object' && !Array.isArray(body)) msg = String(body.Message ?? body.message ?? body.error ?? '');
if (status >= 400 && typeof body === 'string' && !body.trim().startsWith('<')) msg = body.slice(0, 600);
msg = msg.replace(/((?:api[_-]?key|token|secret)[\s"'=:\-]+)[^\s"'&,}]+/gi, '$1[OCULTO]').replace(/Bearer\s+\S+/gi, 'Bearer [OCULTO]');
return [{json:{caminho:'A - API Key na query',statusCode:status,contentType:h['content-type'] ?? null,retryAfter:h['retry-after'] ?? null,respostaRecebida:status>0,sucessoHttp:status>=200 && status<300,mensagemErro:msg || null,tamanhoResposta:typeof raw==='string'?raw.length:JSON.stringify(raw).length,observacao:'Uma chamada real, Take=1, sem CNPJ, sem datas e sem repeticao. XML e credenciais nao sao incluidos neste resumo.'}}];
